	var perPixelLighting : Bool};
	var pixelColor:Vec4;
	var lightPixelColor:Vec3;
	var lightColor:Vec3;
	@const var additive:Bool;
	function __init__() {
		lightColor = additive ? global.ambientLight : vec3(0.);
	};
	function __init__fragment() {
		lightPixelColor = additive ? global.ambientLight : vec3(0.);
