				var radius = length(aabbMax - center);
				var v = center - pos;
				var vLen2 = dot(v, v);
				var v1 = dot(v, dir);
				var distClosest = cosAngle * sqrt(max(vLen2 - v1 * v1, 0.0)) - v1 * sinAngle;
				if (!(distClosest > radius || v1 < -radius)) pushLight(l);
