			var screenRayDir = secondScreenPos - screenPos;
			screenRayDir /= abs(screenRayDir.z);
			var facingCamera = camera.reverseDepth ? screenRayDir.z >= 0.0 : screenRayDir.z <= 0.0;
			var t0 = (vec2(0.0) - screenPos.xy) / screenRayDir.xy;
			var t1 = (vec2(1.0) - screenPos.xy) / screenRayDir.xy;
			var t2 = max(t0, t1);
			var tMax = min(t2.x, t2.y);
			var crossStep = vec2(screenRayDir.x < 0.0 ? -1.0 : 1.0, screenRayDir.y < 0.0 ? -1.0 : 1.0);
			var crossOffset = crossStep * 0.000001;
			crossStep = saturate(crossStep);
			var curLevel = 0;
			var curIteration = stepCount;
			var t:Float;
			{
				var cellCount = computeCellCount(curLevel);
				var cellIndex = computeCellIndex(screenPos.xy, cellCount);
				var newCellIndex = cellIndex + crossStep;
				var newCellPos = (newCellIndex / cellCount) + crossOffset;
				var posT = (newCellPos - screenPos.xy) / screenRayDir.xy;
				var edgeT = min(posT.x, posT.y);
				t = edgeT;
			};
			while (curLevel >= 0 && curIteration > 0 && t < tMax) {
				var curScreenPos = screenPos + screenRayDir * t;
				var cellCount = computeCellCount(curLevel);
				var cellIndex = computeCellIndex(curScreenPos.xy, cellCount);
				var cellDepth = depthMap.fetchLod(ivec2(cellIndex), curLevel).x;
				var tDepth = (cellDepth - screenPos.z) * screenRayDir.z;
				var newCellIndex = cellIndex + crossStep;
				var newCellPos = (newCellIndex / cellCount) + crossOffset;
				var tNewCell = (newCellPos - screenPos.xy) / screenRayDir.xy;
				var tNextBounds = min(tNewCell.x, tNewCell.y);
				var hit = facingCamera ? (t <= tDepth) : (tDepth <= tNextBounds);
				var mipOffset = hit ? -1 : 1;
				if (curLevel == 0) {
					var z0 = linearizeDepth(cellDepth);
					var z1 = linearizeDepth(curScreenPos.z);
					if (z1 - z0 > depthTolerance) {
						hit = false;
						mipOffset = 0;
					};
				};
				if (!hit) t = tNextBounds else if (!facingCamera) t = max(t, tDepth);
				if (DEBUG) drawDebug(curIteration, screenPos, screenRayDir, curScreenPos, t, max(tNewCell.x, tNewCell.y), curLevel, hit);
				curLevel = min(curLevel + mipOffset, mipMaps - 1);
				--curIteration;
			};
			var curScreenPos = screenPos + screenRayDir * t;
			var validity = 1.0;
			var curPixelPos = ivec2(curScreenPos.xy * screenSize);
			var hitDepth = depthMap.fetch(curPixelPos).x;
			if (t >= tMax || hitDepth == farPlane) validity = 0.0;
			if (abs(screenRayDir.x * t) < 2.0 / screenSize.x && abs(screenRayDir.y * t) < 2.0 / screenSize.y) {
				var hitNormal = normalMap.fetch(curPixelPos).xyz * camera.view.mat3();
				if (dot(viewRayDir, hitNormal) >= 0.0) validity = 0.0;
			};
			var curViewPos = computeViewPos(curScreenPos);
			var hitViewPos = computeViewPos(vec3(curScreenPos.xy, hitDepth));
			var distance = length(curViewPos - hitViewPos);
			var tolerance = depthTolerance + distanceBias * pow(curViewPos.z, distancePowerBias);
			var confidence = 1.0 - step(tolerance, distance);
			validity *= saturate(confidence * confidence);
			validity *= 1.0 - smoothstep(0.5, 0.7, roughness);
			var marginBlend = 1.0;
			var margin = vec2((screenSize.x + screenSize.y) * marginSize);
			{
				var curPixelPos = vec2(curPixelPos);
				var marginGrad = mix(screenSize - curPixelPos, curPixelPos, vec2(curPixelPos.x < screenSize.x * 0.5 ? 1.0 : 0.0, curPixelPos.y < screenSize.y * 0.5 ? 1.0 : 0.0));
				marginBlend = smoothstep(0.0, margin.x * margin.y, marginGrad.x * marginGrad.y);
			};
			var rayLength = length(screenRayDir.xy * t);
			var fadeIn = fadeInExponent == 0.0 ? 1.0 : pow(saturate(rayLength), fadeInExponent);
			var fadeOut = fadeOutExponent == 0.0 ? 1.0 : pow(saturate(1.0 - rayLength), fadeOutExponent);
			var fade = fadeIn * fadeOut;
			if (fade > 0.999) fade = 1.0;
			validity *= marginBlend * fade;
			if (validity > 0.0) color = vec4(hdrMap.getLod(curScreenPos.xy, 0).xyz, 1.0) * validity;
			if (roughness > 0.001) {
				var coneAngle = min(roughness, 0.999) * PI * 0.5;
				var coneLen = rayLength;
				var opLen = 2.0 * tan(coneAngle) * coneLen;
				var blurRadius:Float;
				{
					var a = opLen;
					var h = coneLen;
					var a2 = a * a;
					var fh2 = 4.0 * h * h;
					blurRadius = (a * (sqrt(a2 + fh2) - a)) / (4.0 * h);
				};
				mipLevel = clamp(log2(blurRadius * max(screenSize.x, screenSize.y) / 16.0 + 1.0), 0.0, float(mipMaps - 1));
			};
			mipLevel *= pow(clamp(1.25 - rayLength, 0.0, 1.0), 0.2);
		};
		outputColor.store(pixelPos, color);
		outputMipLevel.store(pixelPos, mipLevel / 14.0);
	};
}

{
	var albedo:Vec3;
	var depth:Float;
	var normal:Vec3;
	var metalness:Float;
	var roughness:Float;
	var occlusion:Float;
	var emissive:Float;
	var custom1:Float = 0.0;
	var custom2:Float = 0.0;
	@param var shadowMap:Channel;
	@param var shadowMapCube:SamplerCube;
	@param var velocity:Sampler2D;
	@param var translucencyMap:Sampler2D;
	@const var shadowIsCube:Bool;
	@const var smode:Int;
	@const var HAS_VELOCITY:Bool;
	@const var HAS_TRANSLUCENCY:Bool;
	var transformedPosition:Vec3;
	@global var camera:{ var view : Mat4; var viewProj : Mat4};
	@const var HAS_CLUSTERS:Bool;
	@param var clusterData:StorageBuffer<Int>;
	@param var clusterZParams:Vec2;
	@param var clearDepth:Float;
	@param var sceneColor:Sampler2D;
	var CLUSTER_X:Int = 16;
	var CLUSTER_Y:Int = 9;
	var CLUSTER_Z:Int = 24;
	var CLUSTER_STRIDE:Int = 128;
	var CLUSTER_HEAT_MAX:Float = 32.0;
	function heat(t:Float):Vec3 {
		var j = 0.125 + saturate(t) * 0.75;
		return saturate(vec3(1.5 - abs(4.0 * j - 3.0), 1.5 - abs(4.0 * j - 2.0), 1.5 - abs(4.0 * j - 1.0)));
	};
	function clusterColor():Vec3 {
		var gray = vec3(dot(sceneColor.get(calculatedUV).rgb, vec3(0.299, 0.587, 0.114)) * 0.4);
		var color = gray;
		if (HAS_CLUSTERS) {
			var p = vec4(transformedPosition, 1.) * camera.viewProj;
			var grid = (p.xy / p.w * 0.5 + 0.5) * vec2(float(CLUSTER_X), float(CLUSTER_Y));
			var tile = clamp(floor(grid), vec2(0.), vec2(float(CLUSTER_X - 1), float(CLUSTER_Y - 1)));
			var viewZ = (transformedPosition * camera.view.mat3x4()).z;
			var slice = clamp(floor(log(max(viewZ, 1e-6)) * clusterZParams.x + clusterZParams.y), 0., float(CLUSTER_Z - 1));
			var counts = clusterData[((int(slice) * CLUSTER_Y + int(tile.y)) * CLUSTER_X + int(tile.x)) * CLUSTER_STRIDE];
			var count = (counts & 0xFF) + ((counts >> 8) & 0xFF) + ((counts >> 16) & 0xFF) + ((counts >> 24) & 0xFF);
			if (count >= CLUSTER_STRIDE - 1) color = vec3(1., 0., 1.) else if (count > 0) color = mix(gray, heat(float(count) / CLUSTER_HEAT_MAX), 0.75);
			var edge = abs(fract(grid) - 0.5);
			if (max(edge.x, edge.y) > 0.48) color = vec3(0.5);
		};
		return color;
	};
	function getColor(x:Float, y:Float):Vec3 {
		var color:Vec3;
		if (y < 1) {
			if (x < 1) color = albedo.sqrt() else if (x < 2) color = packNormal(normal).rgb else color = depth.xxx;
		} else if (y < 2) {
			if (x < 1) color = metalness.xxx else if (x < 2) color = roughness.xxx else if (x < 3) color = occlusion.xxx;
		} else if (y < 3) {
			if (x < 1) color = vec3(emissive, custom1, custom2) else if (x < 2) {
				var uv = vec2(x - 1, y - 2);
				if (shadowIsCube) {
					var phi = (1 - uv.x) * 3.1415 * 2;
					var theta = (-uv.y + 0.5) * 3.1415;
					var dir = vec3(cos(phi) * cos(theta), sin(phi) * cos(theta), sin(theta));
					color = shadowMapCube.get(dir).xxx;
				} else color = shadowMap.get(uv).xxx;
			} else if (HAS_VELOCITY) {
				color = vec3(abs(velocity.get(input.uv).xy) * 100.0, 0.0);
			};
		} else {
			if (x < 1) {
				if (HAS_TRANSLUCENCY) color = translucencyMap.get(vec2(x, y - 3)).rgb;
			} else if (x < 2) color = clusterColor();
		};
		return color;
	};
	function fragment() {
		var color:Vec3;
		var x = input.uv.x * 3;
		var y = input.uv.y * 4;
		if (smode == 0) color = getColor(x, y) else color = getColor((smode - 1) % 3 + input.uv.x, int((smode - 1) / 3) + input.uv.y);
		pixelColor = vec4(color, 1.);
	};
}

{
	var output:{ var albedoStrength : Float; var normalStrength : Float; var pbrStrength : Float; var emissiveStrength : Float};
	var pixelColor:Vec4;
	@param var albedoStrength:Float;
	@param var normalStrength:Float;
	@param var pbrStrength:Float;
	@param var emissiveStrength:Float;
	function fragment() {
		output.albedoStrength = albedoStrength * pixelColor.a;
		output.normalStrength = normalStrength * pixelColor.a;
		output.pbrStrength = pbrStrength * pixelColor.a;
		output.emissiveStrength = emissiveStrength * pixelColor.a;
	};
}

{
	@param var hdrTexture:Sampler2D;
	@param var exposureExp:Float;
	@const var isSRBG:Bool;
	@const var mode:Int;
	@param var invGamma:Float;
	@param var a:Float;
	@param var b:Float;
	@param var c:Float;
	@param var d:Float;
	@param var e:Float;
	var hdrColor:Vec4;
	function __init__fragment() {
		hdrColor = hdrTexture.get(calculatedUV);
	};
	function fragment() {
		var color = hdrColor;
		color.rgb *= exposureExp;
		switch (mode) {
			case 0:
				color.rgb = color.rgb.saturate();			
			case 1:
				color.rgb = color.rgb / (color.rgb + vec3(1.));			
			case 2:
				color.rgb = saturate((color.rgb * (a * color.rgb + b)) / (color.rgb * (c * color.rgb + d) + e));			
			case 3:
				var startCompression = 0.8 - 0.04;
				var desaturation = 0.15;
				var x = min(color.r, min(color.g, color.b));
				var offset = x < 0.08 ? x - 6.25 * x * x : 0.04;
				color.rgb -= offset;
				var peak = max(color.r, max(color.g, color.b));
				if (peak >= startCompression) {
					var dd = 1. - startCompression;
					var newPeak = 1. - dd * dd / (peak + dd - startCompression);
					color.rgb *= newPeak / peak;
					var g = 1. - 1. / (desaturation * (peak - newPeak) + 1.);
					color.rgb = mix(color.rgb, vec3(newPeak), g);
				};			
		};
		if (!isSRBG) color.rgb = pow(color.rgb, vec3(invGamma));
		pixelColor = color;
	};
}

{
	@global var global:{ var pixelSize : Vec2; @perObject
	var modelView : Mat4; @perObject
	var modelViewInverse : Mat4};
	@global var camera:{ var inverseViewProj : Mat4};
	@const var USE_NORMAL_FADE:Bool;
	@global var depthMap:Channel;
	@param var fadePower:Float;
	@param var fadeStart:Float;
	@param var fadeEnd:Float;
	@param var normalFadeStart:Float;
	@param var normalFadeEnd:Float;
	var calculatedUV:Vec2;
	var transformedTangent:Vec4;
	var transformedNormal:Vec3;
	var pixelTransformedPosition:Vec3;
	var projectedPosition:Vec4;
	var pixelColor:Vec4;
	var fadeFactor:Float;
	var modelView:Mat4;
	function normalFade(worldNormal:Vec3) {
		var z = normalize(vec3(0, 0, 1) * modelView.mat3());
		var angle = 1 - abs(acos(z.dot(worldNormal)) / PI);
		var f = saturate((angle - normalFadeStart) / (normalFadeEnd - normalFadeStart));
		fadeFactor *= f;
	};
	function getWorlPos(pos:Vec2):Vec3 {
		var depth = depthMap.get(screenToUv(pos)).r;
		var ruv = vec4(pos, depth, 1);
		var wpos = ruv * camera.inverseViewProj;
		var result = (wpos.xyz / wpos.w);
		return result;
	};
	function getWorldNormal():Vec3 {
		var screenPos = projectedPosition.xy / projectedPosition.w;
		var worldPos = getWorlPos(screenPos);
		var ddx = worldPos - getWorlPos(screenPos + vec2(global.pixelSize.x, 0));
		var ddy = worldPos - getWorlPos(screenPos + vec2(0, global.pixelSize.y));
		return normalize(cross(ddy, ddx));
	};
	function outsideBounds(localPos:Vec3):Bool {
		return (localPos.x > 0.5 || localPos.x < -0.5 || localPos.y > 0.5 || localPos.y < -0.5 || localPos.z > 0.5 || localPos.z < -0.5);
	};
}

{
	var output:{ var color : Vec4};
	@const var CENTERED:Bool;
	@const var GAMMA_CORRECT:Bool;
	@const var AUTO_ALPHA:Bool = true;
	@param var emissive:Float;
	@param var colorTexture:Sampler2D;
	var modelViewInverse:Mat4;
	function __init__fragment() {
		{
			var matrix = camera.inverseViewProj * modelViewInverse;
			var screenPos = projectedPosition.xy / projectedPosition.w;
			var depth = depthMap.get(screenToUv(screenPos));
			var ruv = vec4(screenPos, depth, 1);
			var wpos = ruv * matrix;
			var ppos = ruv * camera.inverseViewProj;
			pixelTransformedPosition = ppos.xyz / ppos.w;
			var localPos = (wpos.xyz / wpos.w);
			calculatedUV = localPos.xy;
			fadeFactor = 1 - clamp(pow(max(0.0, abs(localPos.z * 2) - fadeStart) / (fadeEnd - fadeStart), fadePower), 0, 1);
			if (CENTERED) calculatedUV += 0.5;
			if (outsideBounds(localPos)) discard;
		};
	};
	function fragment() {
		if (USE_NORMAL_FADE) {
			var worldNormal = getWorldNormal();
			normalFade(worldNormal);
		};
		var color = colorTexture.get(calculatedUV);
		pixelColor.rgb *= color.rgb;
		if (GAMMA_CORRECT) pixelColor.rgb *= pixelColor.rgb;
		pixelColor.rgb += pixelColor.rgb * emissive;
		if (AUTO_ALPHA) pixelColor.a = clamp(max(max(pixelColor.r, pixelColor.g), pixelColor.b), 0, 1) * fadeFactor else pixelColor.a = color.a * fadeFactor;
	};
}

{
	var output:{ var albedoStrength : Float; var normalStrength : Float; var pbrStrength : Float; var emissiveStrength : Float};
	@const var CENTERED:Bool;
	@const var USE_ALBEDO:Bool;
	@const var USE_NORMAL:Bool;
	@param var albedoStrength:Float;
	@param var normalStrength:Float;
	@param var pbrStrength:Float;
	@param var emissiveStrength:Float;
	@param var normal:Vec3;
	@param var tangent:Vec3;
	@param var albedoTexture:Sampler2D;
	@param var normalTexture:Sampler2D;
	var modelViewInverse:Mat4;
	function __init__vertex() {
		transformedNormal = (normal * modelView.mat3()).normalize();
		transformedTangent = vec4((tangent * modelView.mat3()).normalize(), 1.);
	};
	function __init__fragment() {
		{
			var matrix = camera.inverseViewProj * modelViewInverse;
			var screenPos = projectedPosition.xy / projectedPosition.w;
			var depth = depthMap.get(screenToUv(screenPos));
			var ruv = vec4(screenPos, depth, 1);
			var wpos = ruv * matrix;
			var localPos = (wpos.xyz / wpos.w);
			if (outsideBounds(localPos)) discard;
			calculatedUV = localPos.xy;
			fadeFactor = 1 - clamp(pow(max(0.0, abs(localPos.z * 2) - fadeStart) / (fadeEnd - fadeStart), fadePower), 0, 1);
			if (CENTERED) calculatedUV += 0.5;
		};
		output.albedoStrength = USE_ALBEDO ? albedoStrength * pixelColor.a * fadeFactor : 0.0;
		output.normalStrength = USE_NORMAL ? normalStrength * pixelColor.a * fadeFactor : 0.0;
		output.pbrStrength = pbrStrength * pixelColor.a * fadeFactor;
		output.emissiveStrength = emissiveStrength * pixelColor.a * fadeFactor;
	};
	function fragment() {
		if (USE_ALBEDO) {
			var albedo = albedoTexture.get(calculatedUV);
			pixelColor *= albedo;
		};
		var worldNormal = vec3(0);
		if (USE_NORMAL || USE_NORMAL_FADE) worldNormal = getWorldNormal();
		if (USE_NORMAL) {
			var worldTangent = cross(worldNormal, vec3(0, 1, 0));
			var normal = normalTexture.get(calculatedUV).rgba;
			var n = worldNormal;
			var nf = unpackNormal(normal);
			var tanX = worldTangent.xyz.normalize();
			var tanY = n.cross(tanX) * -1;
			transformedNormal = (nf.x * tanX + nf.y * tanY + nf.z * n).normalize();
		};
		if (USE_NORMAL_FADE) {
			normalFade(worldNormal);
		};
	};
}

class.haxe_doc:
Base class for exceptions.

	If this class (or derivatives) is used to catch an exception, then
	`haxe.CallStack.exceptionStack()` will not return a stack for the exception
	caught. Use `haxe.Exception.stack` property instead:
	```haxe
	try {
		throwSomething();
	} catch(e:Exception) {
		trace(e.stack);
	}
	```

	Custom exceptions should extend this class:
	```haxe
	class MyException extends haxe.Exception {}
	//...
	throw new MyException('terrible exception');
	```

	`haxe.Exception` is also a wildcard type to catch any exception:
	```haxe
	try {
		throw 'Catch me!';
	} catch(e:haxe.Exception) {
		trace(e.message); // Output: Catch me!
	}
	```

	To rethrow an exception just throw it again.
	Haxe will try to rethrow an original native exception whenever possible.
	```haxe
	try {
		var a:Array<Int> = null;
		a.push(1); // generates target-specific null-pointer exception
	} catch(e:haxe.Exception) {
		throw e; // rethrows native exception instead of haxe.Exception
	}
	```

trace.haxe_doc:
Outputs `v` in a platform-dependent way.

		The second parameter `infos` is injected by the compiler and contains
		information about the position where the `trace()` call was made.

		This method can be rebound to a custom function:

			var oldTrace = haxe.Log.trace; // store old function
			haxe.Log.trace = function(v, ?infos) {
			  // handle trace
			}
			...
			haxe.Log.trace = oldTrace;

		If it is bound to null, subsequent calls to `trace()` will cause an
		exception.

abstract.haxe_doc:
A special type that represents a "rest" function argument.

	The special `...` syntax can be used for convenience and improved readability:

	```haxe
	function f(...rest:Int) {
		$type(rest); // haxe.Rest<Int>
	}

	f(1, 2, 3);

	final array = [1, 2, 3];
	f(...array);
	```

	Should be used as a type for the last argument of a method, indicating that
	an arbitrary number of arguments of the given type can be passed to that method.

	Allows to use array access by index to get values of rest arguments.
	If the index exceeds the amount of rest arguments passed, the result is unspecified.

blit.haxe_doc:
Copies `len` bytes from `src` into this instance.
		@param pos Zero-based location in `this` instance at which to start writing
			bytes.
		@param src Source `Bytes` instance from which to copy bytes.
		@param srcpos Zero-based location at `src` from which bytes will be copied.
		@param len Number of bytes to be copied.

class.haxe_doc:
`ArrayBufferView` is a helper type representing any of the following JavaScript `TypedArray` types:

	Documentation [ArrayBufferView](https://developer.mozilla.org/en-US/docs/Web/API/ArrayBufferView) by [Mozilla Contributors](https://developer.mozilla.org/en-US/docs/Web/API/ArrayBufferView$history), licensed under [CC-BY-SA 2.5](https://creativecommons.org/licenses/by-sa/2.5/).

	@see <https://developer.mozilla.org/en-US/docs/Web/API/ArrayBufferView>

IntMap allows mapping of Int keys to arbitrary values.

	See `Map` for documentation details.

	@see https://haxe.org/manual/std-Map.html

StringMap allows mapping of String keys to arbitrary values.

	See `Map` for documentation details.

	@see https://haxe.org/manual/std-Map.html

abstract.haxe_doc:
A Vector is a storage of fixed size. It can be faster than Array on some
	targets, and is never slower.

	@see https://haxe.org/manual/std-vector.html

typedef.haxe_doc:
Represents a AST node identical to `Expr`, but it allows constraining the
	type of accepted expressions.
	@see https://haxe.org/manual/macro-ExprOf.html

TExtend.haxe_doc:
Represents typedef extensions `> Iterable<T>`.
		The array `p` holds the type paths to the given types.
		@see https://haxe.org/manual/type-system-extensions.html

APrivate.haxe_doc:
Private access modifier, grants access to class and its sub-classes
		only.
		@see https://haxe.org/manual/class-field-visibility.html

AInline.haxe_doc:
Inline access modifier. Allows expressions to be directly inserted in
		place of calls to them.
		@see https://haxe.org/manual/class-field-inline.html

typedef.haxe_doc:
This class can be added via `using haxe.macro.Tools` in order to enable `using` functionality on these macro tool classes:
- `haxe.macro.ExprTools` - `haxe.macro.ComplexTypeTools` - `haxe.macro.TypeTools` - `haxe.macro.MacroStringTools` - `haxe.macro.TypedExprTools` - `haxe.macro.PositionTools`
@see <https://haxe.org/manual/lf-static-extension.html>

